"use client";

import "leaflet/dist/leaflet.css";
import { useEffect,useMemo,useRef,useState } from "react";
import { ArrowSquareOut,Buildings,Compass,MapPin,ShieldCheck,Sparkle,Star,TrendUp } from "@phosphor-icons/react";
import type { CityMapRankV30 } from "@/lib/ai/city-map-ranking-v30";

type Lang="el"|"en";
type MapPayload={version:number;generatedAt:string;month:number;cities:CityMapRankV30[];sources:Record<string,string>;rankingModel:Record<string,string>};
type TripadvisorPlace={locationId:string;name:string;rating:number|null;reviewCount:number|null;ranking:number|null;rankingLabel:string|null;webUrl:string|null};
type DetailPayload={
 destination:{slug:string;nameEl:string;nameEn:string;tags:string[]};
 tripadvisorSignal:{status:string;rating5:number|null;reviewCount:number;bestRanking:number|null;sampleSize:number;sourceMonth:string};
 tripadvisor:{status:string;places:TripadvisorPlace[];restaurants:TripadvisorPlace[];beaches:TripadvisorPlace[];museums:TripadvisorPlace[];nightlife:TripadvisorPlace[];note:string};
 booking:{status:string;reviewScore10:number|null;reviewCount:number;accommodationCount:number;sourceDate:string};
 stayWindow:{startDate:string;endDate:string;offers:Array<{propertyName:string;price:number|null;currency:string|null;trackingUrl:string;validTo:string|null}>};
 trustPolicy:string;
};

const say=(lang:Lang,el:string,en:string)=>lang==="el"?el:en;
const months=["Ιαν","Φεβ","Μαρ","Απρ","Μάι","Ιούν","Ιούλ","Αύγ","Σεπ","Οκτ","Νοέ","Δεκ"];
const monthsEn=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const stars=(score100:number)=>Math.max(0,Math.min(5,score100/20));
const escapeHtml=(value:string)=>value.replace(/[&<>'"]/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[char]??char));

export function AiDestinationMapV30({lang="el"}:{lang?:Lang}){
 const nowMonth=Number(new Intl.DateTimeFormat("en",{month:"numeric",timeZone:"Europe/Athens"}).format(new Date()));
 const[month,setMonth]=useState(nowMonth),[payload,setPayload]=useState<MapPayload|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState<string|null>(null),[selectedSlug,setSelectedSlug]=useState<string|null>(null),[detail,setDetail]=useState<DetailPayload|null>(null),[detailLoading,setDetailLoading]=useState(false);
 const hostRef=useRef<HTMLDivElement|null>(null),mapRef=useRef<import("leaflet").Map|null>(null),markerRef=useRef(new Map<string,import("leaflet").Marker>()),selectedRef=useRef<string|null>(null);
 selectedRef.current=selectedSlug;

 useEffect(()=>{const controller=new AbortController();setLoading(true);setError(null);fetch(`/api/ai-map?lang=${lang}&month=${month}`,{signal:controller.signal,headers:{accept:"application/json"}}).then(async response=>{if(!response.ok)throw new Error(`map ${response.status}`);return await response.json() as MapPayload}).then(data=>{setPayload(data);setSelectedSlug(current=>current&&data.cities.some(city=>city.slug===current)?current:data.cities[0]?.slug??null)}).catch(err=>{if(err?.name!=="AbortError")setError(say(lang,"Ο ημερήσιος AI χάρτης δεν είναι διαθέσιμος αυτή τη στιγμή.","The daily AI map is temporarily unavailable."))}).finally(()=>setLoading(false));return()=>controller.abort()},[lang,month]);

 useEffect(()=>{if(!selectedSlug){setDetail(null);return}const controller=new AbortController();setDetailLoading(true);setDetail(null);fetch(`/api/ai-map/${encodeURIComponent(selectedSlug)}?lang=${lang}`,{signal:controller.signal,headers:{accept:"application/json"}}).then(async response=>{if(!response.ok)throw new Error(`detail ${response.status}`);return await response.json() as DetailPayload}).then(setDetail).catch(()=>setDetail(null)).finally(()=>setDetailLoading(false));return()=>controller.abort()},[selectedSlug,lang]);

 const cities=payload?.cities??[],selected=useMemo(()=>cities.find(city=>city.slug===selectedSlug)??null,[cities,selectedSlug]);

 useEffect(()=>{let cancelled=false;async function mount(){if(!hostRef.current||mapRef.current||!cities.length)return;const L=await import("leaflet");if(cancelled||!hostRef.current)return;const map=L.map(hostRef.current,{zoomControl:true,scrollWheelZoom:true,attributionControl:false,minZoom:5}).setView([38.45,23.4],6);mapRef.current=map;L.tileLayer(process.env.NEXT_PUBLIC_MAP_TILE_URL||"https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:18,minZoom:5}).addTo(map);const bounds:Array<[number,number]>=[];for(const city of cities){const active=city.slug===selectedRef.current,icon=L.divIcon({className:"ai-map-marker-shell",html:`<span class="ai-map-marker${active?" active":""}"><b>${city.rank}</b><small>${city.aiScore}</small></span>`,iconSize:[48,56],iconAnchor:[24,52],tooltipAnchor:[0,-46]});const marker=L.marker([city.latitude,city.longitude],{icon,keyboard:true,title:lang==="el"?city.nameEl:city.nameEn}).addTo(map).bindTooltip(`<strong>${escapeHtml(lang==="el"?city.nameEl:city.nameEn)}</strong><br/>AI ${city.aiScore}/100`,{direction:"top",offset:[0,-42]});marker.on("click",()=>setSelectedSlug(city.slug));markerRef.current.set(city.slug,marker);bounds.push([city.latitude,city.longitude])}if(bounds.length)map.fitBounds(bounds,{padding:[42,42],maxZoom:7});window.setTimeout(()=>map.invalidateSize(),100)}void mount();return()=>{cancelled=true;markerRef.current.clear();mapRef.current?.remove();mapRef.current=null}},[cities,lang]);

 useEffect(()=>{markerRef.current.forEach((marker,slug)=>{const el=marker.getElement()?.querySelector(".ai-map-marker");el?.classList.toggle("active",slug===selectedSlug);if(slug===selectedSlug){marker.openTooltip();const point=marker.getLatLng();mapRef.current?.panTo(point,{animate:true,duration:.35})}})},[selectedSlug]);

 function pick(slug:string){setSelectedSlug(slug)}
 const taPlaces=detail?[...(detail.tripadvisor.places??[]),...(detail.tripadvisor.restaurants??[]),...(detail.tripadvisor.beaches??[])].filter((item,index,array)=>array.findIndex(other=>other.locationId===item.locationId)===index).sort((a,b)=>(b.rating??0)-(a.rating??0)||(b.reviewCount??0)-(a.reviewCount??0)).slice(0,4):[];

 return <main className="ai-map-v30">
  <section className="ai-map-hero">
   <div><span><Sparkle size={16} weight="fill"/> AI DESTINATION RADAR · V30</span><h1>{say(lang,"Ο χάρτης που κατατάσσει την Ελλάδα κάθε μέρα.","The map that ranks Greece every day.")}</h1><p>{say(lang,"Εποχικότητα, πραγματικό inventory, πρόσβαση και — όταν είναι διαθέσιμα — Tripadvisor και Booking.com evidence. Κανένα rating δεν επινοείται.","Seasonality, real inventory, access and — when available — Tripadvisor and Booking.com evidence. No rating is invented.")}</p></div>
   <a href={lang==="el"?"/":"/en"}><Compass size={18}/>{say(lang,"Πίσω στο AI planner","Back to AI planner")}</a>
  </section>
  <section className="ai-map-months" aria-label={say(lang,"Μήνας ταξιδιού","Travel month")}>{Array.from({length:12},(_,index)=>index+1).map(value=><button key={value} className={month===value?"active":""} onClick={()=>setMonth(value)}>{lang==="el"?months[value-1]:monthsEn[value-1]}</button>)}</section>
  {error&&<div className="ai-map-error">{error}</div>}
  <section className="ai-map-workspace">
   <aside className="ai-map-ranking">
    <div className="ai-map-ranking-head"><span>{say(lang,"ΗΜΕΡΗΣΙΑ ΚΑΤΑΤΑΞΗ","DAILY RANKING")}</span><strong>{loading?say(lang,"Ανανεώνεται…","Refreshing…"):say(lang,`${cities.length} κορυφαίοι προορισμοί`,`${cities.length} top destinations`)}</strong></div>
    <div className="ai-map-list">{cities.map(city=><button key={city.slug} className={city.slug===selectedSlug?"active":""} onClick={()=>pick(city.slug)}><span className="rank">#{city.rank}</span><span className="city"><strong>{lang==="el"?city.nameEl:city.nameEn}</strong><small>{city.regionGroup} · {city.propertyCount} {say(lang,"stays","stays")}</small></span><span className="score"><strong>{city.aiScore}</strong><small>AI /100</small></span></button>)}</div>
   </aside>
   <div className="ai-map-stage">
    <div ref={hostRef} className="ai-map-canvas" aria-label={say(lang,"Διαδραστικός χάρτης κορυφαίων προορισμών","Interactive map of top destinations")}/><small className="ai-map-attribution">© OpenStreetMap contributors · ODbL</small>
    {selected&&<article className="ai-map-summary">
      <div className="ai-map-summary-top"><span>#{selected.rank}</span><div><small>{selected.regionGroup}</small><h2>{lang==="el"?selected.nameEl:selected.nameEn}</h2></div><div className="ai-overall"><strong>{selected.aiScore}</strong><small>AI / 100</small></div></div>
      <div className="ai-starline"><Star size={18} weight="fill"/><strong>{stars(selected.aiScore).toFixed(1)}/5</strong><span>{say(lang,"AI composite — όχι review stars","AI composite — not review stars")}</span></div>
      <div className="ai-map-metrics"><span><TrendUp size={17}/><b>{selected.seasonScore}</b>{say(lang,"Εποχή","Season")}</span><span><Buildings size={17}/><b>{selected.supplyScore}</b>{say(lang,"Inventory","Inventory")}</span><span><MapPin size={17}/><b>{selected.routeScore}</b>{say(lang,"Πρόσβαση","Access")}</span></div>
      <div className="ai-map-evidence">
       <section><header><strong>Tripadvisor</strong>{selected.tripadvisor?.status==="live"&&selected.tripadvisor.rating5!=null?<span><Star size={15} weight="fill"/>{selected.tripadvisor.rating5.toFixed(1)}/5</span>:<span>{say(lang,"χωρίς live data","no live data")}</span>}</header>{selected.tripadvisor?.status==="live"?<p>{selected.tripadvisor.reviewCount.toLocaleString(lang==="el"?"el-GR":"en-GB")} reviews · {selected.tripadvisor.sampleSize} verified POIs</p>:<p>{say(lang,"Εμφανίζεται μόνο όταν απαντά το επίσημο API.","Shown only when the official API returns evidence.")}</p>}</section>
       <section><header><strong>Booking.com</strong>{selected.booking?.status==="live"&&selected.booking.reviewScore10!=null?<span>{selected.booking.reviewScore10.toFixed(1)}/10</span>:<span>{selected.booking?.status==="not-configured"?say(lang,"API αναμένεται","API pending"):say(lang,"χωρίς score","no score")}</span>}</header><p>{selected.booking?.status==="live"?`${selected.booking.accommodationCount} ${say(lang,"διαθέσιμα accommodations στο daily check","accommodations in the daily check")}`:say(lang,"Δεν χρησιμοποιείται εκτιμώμενο Booking score.","No estimated Booking score is used.")}</p></section>
      </div>
      <div className="ai-map-detail"><h3>{say(lang,"Trusted evidence για την πόλη","Trusted evidence for this destination")}</h3>{detailLoading?<p>{say(lang,"Φορτώνω reviews και πηγές…","Loading reviews and sources…")}</p>:detail?<><div className="ai-map-pois">{taPlaces.map(place=><a key={place.locationId} href={place.webUrl??"#"} target={place.webUrl?"_blank":undefined} rel="noreferrer"><span><strong>{place.name}</strong><small>{place.rankingLabel??say(lang,"Tripadvisor place","Tripadvisor place")}</small></span><span>{place.rating!=null?`${place.rating.toFixed(1)} ★`:"—"}<small>{place.reviewCount!=null?`${place.reviewCount.toLocaleString()} reviews`:""}</small></span>{place.webUrl&&<ArrowSquareOut size={15}/>}</a>)}</div><div className="ai-map-offers">{detail.stayWindow.offers.slice(0,3).map(offer=><a key={`${offer.propertyName}-${offer.trackingUrl}`} href={offer.trackingUrl} target="_blank" rel="nofollow sponsored noreferrer"><Buildings size={16}/><span><strong>{offer.propertyName}</strong><small>{offer.price!=null?`${offer.price.toFixed(0)} ${offer.currency??"EUR"}`:say(lang,"Δες τιμή","See price")}</small></span><ArrowSquareOut size={15}/></a>)}</div><p className="trust"><ShieldCheck size={16}/>{detail.trustPolicy}</p></>:<p>{say(lang,"Δεν υπάρχουν πρόσθετα verified details αυτή τη στιγμή.","No additional verified details are available right now.")}</p>}</div>
    </article>}
   </div>
  </section>
 </main>
}

"use client";

import { useEffect,useMemo,useRef,useState } from "react";
import { TripadvisorProofV25 } from "@/components/tripadvisor-proof-v25";
import type { TripBuilderPlanV25,TripadvisorPlaceV25 } from "@/lib/trip-builder/types-v25";
import type { TripRequest } from "@/lib/validation/trip";
import type { V8StayOffer,V8StayResponse } from "@/lib/decision/v8-types";
import styles from "./post-stay-trip-builder-v25.module.css";

type Context={trip:TripRequest|null;slug:string|null;offers:V8StayOffer[];startDate:string|null;endDate:string|null};
type Selection={trip:TripRequest;slug:string;offer:V8StayOffer};
type TravelWindow=Window&{__travelV25Context?:Context;__travelV25FetchWrapped?:boolean};
const EVENT="travel:v25-stay-selected",DAY=86_400_000;
const addDays=(iso:string,days:number)=>new Date(Date.parse(`${iso}T00:00:00Z`)+days*DAY).toISOString().slice(0,10);
const pretty=(iso:string,lang:"el"|"en")=>new Intl.DateTimeFormat(lang==="el"?"el-GR":"en-GB",{weekday:"short",day:"numeric",month:"short"}).format(new Date(`${iso}T12:00:00Z`));
const say=(lang:"el"|"en",el:string,en:string)=>lang==="el"?el:en;
function truthLabel(state:TripBuilderPlanV25["availability"]["state"],lang:"el"|"en"){const map:Record<typeof state,[string,string]>={CONFIRMED_ACTIVE:["Το feed δηλώνει ενεργό","Feed marks active"],VALID_WINDOW_STOCK_UNKNOWN:["Οι ημερομηνίες καλύπτονται · stock άγνωστο","Dates covered · stock unknown"],EXPLICITLY_UNAVAILABLE:["Μη διαθέσιμο","Unavailable"],NOT_IN_FEED:["Δεν υπάρχει στο feed για αυτές τις ημερομηνίες","Not in feed for these dates"],PROVIDER_PAGE_REACHED:["Οι ημερομηνίες πέρασαν στη σελίδα παρόχου · τελική επιβεβαίωση εκεί","Dates passed to provider · confirm there"],PROVIDER_UNAVAILABLE:["Ο πάροχος επέστρεψε μη διαθεσιμότητα","Provider returned unavailable"],PROVIDER_PROBE_UNAVAILABLE:["Δεν έγινε ασφαλής live έλεγχος παρόχου","Provider live check unavailable"]};return map[state][lang==="el"?0:1]}
function PlaceCard({item,lang}:{item:TripadvisorPlaceV25;lang:"el"|"en"}){return <article className={styles.card}>{item.imageUrl?<img className={styles.photo} src={item.imageUrl} alt={item.name}/>:null}<small>{item.kind.toUpperCase()}</small><h4>{item.name}</h4><TripadvisorProofV25 item={item}/>{item.description?<p>{item.description.slice(0,260)}</p>:null}{item.address?<p><small>{item.address}</small></p>:null}{item.webUrl?<a href={item.webUrl} target="_blank" rel="noopener noreferrer">{say(lang,"Δες στο Tripadvisor ↗","View on Tripadvisor ↗")}</a>:null}</article>}
function updateOneNightPicker(){const inputs=[...document.querySelectorAll<HTMLInputElement>('input[type="date"]')];if(inputs.length<2)return;const start=inputs[0],end=inputs[1];if(!start.value)return;const desired=addDays(start.value,1);if(end.min!==desired)end.min=desired}
function readSelection(ctx:Context):Selection|null{if(!ctx.trip||!ctx.slug||!ctx.offers.length)return null;const title=document.getElementById("final-step-title")?.textContent?.trim()??"",offer=ctx.offers.find(row=>title.includes(row.propertyName));if(!offer)return null;const startDate=ctx.startDate??ctx.trip.startDate,endDate=ctx.endDate??ctx.trip.endDate,nights=Math.max(1,Math.round((Date.parse(`${endDate}T00:00:00Z`)-Date.parse(`${startDate}T00:00:00Z`))/DAY));return{trip:{...ctx.trip,startDate,endDate,nights},slug:ctx.slug,offer}}

export function PostStayTripBuilderV25(){
 const[plan,setPlan]=useState<TripBuilderPlanV25|null>(null),[loading,setLoading]=useState(false),[error,setError]=useState<string|null>(null),[step,setStep]=useState(1),lastKey=useRef("");const lang:"el"|"en"=plan?.trip.language==="en"?"en":"el";
 useEffect(()=>{const w=window as TravelWindow,ctx=w.__travelV25Context??{trip:null,slug:null,offers:[],startDate:null,endDate:null};w.__travelV25Context=ctx;const originalFetch=window.fetch.bind(window);if(!w.__travelV25FetchWrapped){w.__travelV25FetchWrapped=true;window.fetch=async(input:RequestInfo|URL,init?:RequestInit)=>{const url=typeof input==="string"?input:input instanceof URL?input.toString():input.url,method=(init?.method??(input instanceof Request?input.method:"GET")).toUpperCase();if(url.includes("/api/recommend/stream")&&method==="POST"&&typeof init?.body==="string"){try{ctx.trip=JSON.parse(init.body) as TripRequest}catch{}}const response=await originalFetch(input,init);if(url.includes("/api/destination-detail")&&response.ok){try{const parsed=new URL(url,window.location.origin),payload=await response.clone().json() as V8StayResponse;ctx.slug=payload.slug;ctx.offers=payload.offers??[];ctx.startDate=parsed.searchParams.get("start_date")??payload.startDate;ctx.endDate=parsed.searchParams.get("end_date")??payload.endDate}catch{}}return response}}
 let previous="";const observer=new MutationObserver(()=>{updateOneNightPicker();const selection=readSelection(ctx);if(!selection)return;const key=`${selection.slug}:${selection.offer.sourceProductId}:${selection.trip.startDate}:${selection.trip.endDate}`;if(key===previous)return;previous=key;window.dispatchEvent(new CustomEvent<Selection>(EVENT,{detail:selection}))});observer.observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:["min","value"]});updateOneNightPicker();return()=>observer.disconnect()},[]);
 useEffect(()=>{const handle=(event:Event)=>{const selection=(event as CustomEvent<Selection>).detail;if(!selection)return;const key=`${selection.slug}:${selection.offer.sourceProductId}:${selection.trip.startDate}:${selection.trip.endDate}`;if(lastKey.current===key)return;lastKey.current=key;setLoading(true);setError(null);setPlan(null);setStep(1);void fetch("/api/trip-builder",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({trip:selection.trip,slug:selection.slug,offerId:selection.offer.sourceProductId})}).then(async response=>{if(!response.ok)throw new Error("Trip Builder unavailable");return await response.json() as TripBuilderPlanV25}).then(value=>{setPlan(value);window.setTimeout(()=>document.getElementById("trip-builder-v25")?.scrollIntoView({behavior:"smooth",block:"start"}),120)}).catch(()=>setError("Trip Builder could not verify this stay safely.")).finally(()=>setLoading(false))};window.addEventListener(EVENT,handle);return()=>window.removeEventListener(EVENT,handle)},[]);
 const extra=plan?.budgetBeyondHotel,ta=plan?.tripadvisor,hasTa=ta?.status==="live",allExplore=useMemo(()=>[...(ta?.places??[]),...(ta?.museums??[])],[ta]);
 if(!loading&&!plan&&!error)return <div className={styles.hidden} aria-hidden="true"/>;if(loading&&!plan)return <section id="trip-builder-v25" className={styles.loading}><strong>TRIP BUILDER V25</strong><p>Weather · availability · web research · Tripadvisor · beaches · guide</p></section>;if(error&&!plan)return <section id="trip-builder-v25" className={styles.shell}><div className={styles.empty}>{error}</div></section>;if(!plan)return null;
 return <section id="trip-builder-v25" className={styles.shell}>
  <div className={styles.head}><div><span className={styles.eyebrow}>POST-STAY TRIP BUILDER · V25</span><h2>{say(lang,"Διάλεξες βάση. Τώρα χτίζουμε το πραγματικό ταξίδι.","You chose the base. Now we build the real trip.")}</h2><p>{say(lang,"Οι αρχικές ημερομηνίες μένουν default. Κάθε εναλλακτική κρατά ακριβώς το ίδιο weekday pattern και ελέγχεται ξανά για καιρό και stay truth.","Your original dates stay the default. Every alternative keeps the exact weekday pattern and is rechecked for weather and stay truth.")}</p></div><div className={styles.meta}><strong>{plan.stay?.propertyName}</strong><span>{pretty(plan.trip.startDate,lang)} → {pretty(plan.trip.endDate,lang)} · {plan.trip.nights} {say(lang,"νύχτα/ες","night(s)")}</span><span>{truthLabel(plan.availability.state,lang)}</span></div></div>
  <div className={styles.steps}>{[[1,"Weather & dates"],[2,say(lang,"Τι να δεις","Explore")],[3,say(lang,"Φαγητό & ζωή","Food & life")],[4,say(lang,"Guide & budget","Guide & budget")]].map(([n,label])=><button key={String(n)} className={step===n?styles.active:""} onClick={()=>setStep(Number(n))}>{n}. {label}</button>)}</div>
  {step===1?<div className={styles.panel}><div className={styles.sectionTitle}><div><span className={styles.eyebrow}>{say(lang,"ΒΗΜΑ 1 · ΚΑΙΡΟΣ + ΗΜΕΡΟΜΗΝΙΕΣ","STEP 1 · WEATHER + DATES")}</span><h3>{plan.weather.label}</h3></div><span className={styles.truth}>{truthLabel(plan.availability.state,lang)}</span></div><div className={styles.weatherGrid}>{plan.weather.days.map(day=><article key={day.date} className={styles.weatherDay}><small>{pretty(day.date,lang)}</small><div className={styles.temp}>{day.temperatureMinC==null?"?":Math.round(day.temperatureMinC)}–{day.temperatureMaxC==null?"?":Math.round(day.temperatureMaxC)}°C</div><p>{day.summary}</p>{day.precipitationProbability!=null?<small>{say(lang,"Πιθανότητα βροχής","Rain probability")}: {day.precipitationProbability}%</small>:null}</article>)}</div><div className={styles.flex}><h4>{say(lang,"Εναλλακτικές ίδιων ημερών εβδομάδας","Same-weekday alternatives")}</h4>{plan.flexibleWindows.length?plan.flexibleWindows.map(window=><div className={styles.window} key={window.startDate}><strong>{pretty(window.startDate,lang)} → {pretty(window.endDate,lang)}</strong><small>{window.shiftDays>0?`+${window.shiftDays}`:window.shiftDays} {say(lang,"ημέρες","days")}</small><small>{window.weatherLabel}</small><small>{truthLabel(window.availability.state,lang)} · {window.alternativeStayCount} {say(lang,"άλλα stays","other stays")}</small></div>):<div className={styles.empty}>{say(lang,"Δεν βρέθηκαν ασφαλείς εναλλακτικές.","No safe alternatives found.")}</div>}</div></div>:null}
  {step===2?<div className={styles.panel}><div className={styles.sectionTitle}><div><span className={styles.eyebrow}>{say(lang,"ΒΗΜΑ 2 · INTERNET RESEARCH + ΓΥΡΩ ΣΟΥ","STEP 2 · INTERNET RESEARCH + AROUND YOU")}</span><h3>{say(lang,"Τι αξίζει να δεις — με bullets, πηγές και εικόνες όπου υπάρχουν","What is worth seeing — with bullets, sources and imagery where available")}</h3></div></div>{plan.webResearch.overview?<p>{plan.webResearch.overview}</p>:null}{plan.webResearch.bullets.length?<div className={styles.cards}>{plan.webResearch.bullets.map(item=><article className={styles.card} key={item.name}><small>WEB RESEARCH · {item.strength}</small><h4>{item.name}</h4><p>{item.summary}</p>{item.why?<p><strong>{say(lang,"Γιατί ταιριάζει:","Why it fits:")}</strong> {item.why}</p>:null}</article>)}</div>:null}{hasTa&&allExplore.length?<><h4>{say(lang,"Tripadvisor places / museums με εικόνες","Tripadvisor places / museums with imagery")}</h4><div className={styles.cards}>{allExplore.map(item=><PlaceCard key={`${item.kind}-${item.locationId}`} item={item} lang={lang}/>)}</div></>:null}{!plan.webResearch.bullets.length&&!allExplore.length?<div className={styles.empty}>{say(lang,"Δεν υπάρχει αρκετό verified research για να γεμίσω το βήμα με εικασίες.","There is not enough verified research; the app will not fill this step with guesses.")}</div>:null}<p className={styles.source}>{plan.webResearch.sources.map(source=>source.domain).join(" · ")}{plan.webResearch.sources.length?" · ":""}{ta?.note}</p></div>:null}
